# -*- coding: utf-8 -*-
# RE_PATH (triage record, generated by local_writer v2 / agent fallback):
#   framework : 91jav custom server-rendered framework (layui + plyr)
#   list      : /theme/detail/{tid}/page/{pg}   (page/1 == first page; /{pg} alone is ignored)
#   card      : <a href="/videos/{CODE}"><img class="zximg" z-image-loader-url="..." alt="...">
#   detail    : /videos/{CODE}  ->  var hlsUrl = "https://{cdn}/videos5/{hash}/{hash}.m3u8?sign=..."
#   stream    : signed HLS m3u8 (time-limited sign, re-fetched per detail page)
#   search    : /search/{quote(kw)}/{pg}   (/page/{pg} is ignored, always page 1)
# RE_OBSTACLE:
#   - hlsUrl carries a time-limited signature -> always re-fetch the detail page per play
#   - beyond-the-end category pages answer 404 (not 200+empty) -> clients stop paging
#   - menu categories are JS-driven -> the 18 theme ids are baked in statically
#   - stream CDN host rotates independently of the site host -> do not proxy media

import re
import json
import gzip
import ssl
import threading
import urllib.parse
import urllib.request

try:
    from base.spider import Spider as _BaseSpider
except Exception:
    class _BaseSpider:
        def __init__(self):
            pass

try:
    _SSL_CTX = ssl._create_unverified_context()
except Exception:
    _SSL_CTX = None

NAME = "91jav无码中字"
HOSTS = ["alcohol.kzjdba.cc", "www.91jav1.com"]
UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36")

# 18 static theme categories (homepage menu is JS-driven, only exposes one entry)
CLASSES = [
    ("2", "角色剧情"), ("3", "中文字幕"), ("4", "制服诱惑"), ("5", "直接开啪"),
    ("6", "丝袜美腿"), ("7", "捆绑调教"), ("8", "多P群交"), ("9", "男友视角"),
    ("10", "羞辱强暴"), ("11", "无码高清"), ("12", "盗摄偷拍"), ("13", "女同百合"),
    ("14", "乱伦伦理"), ("15", "人妻诱惑"), ("16", "AV解说"), ("17", "网黄精选"),
    ("18", "性爱知识"), ("19", "英文字幕"),
]

RE_CARD = re.compile("<a href=\"(/videos/[^\"]+)\"\\s*>\\s*<img class=\"zximg\"[^>]*?(?:z-image-loader-url|data-src)=\"([^\"]+)\"[^>]*?alt=\"([^\"]*)\"")
RE_PLAYER = re.compile("var\\s+hlsUrl\\s*=\\s*\"([^\"]+)\"")
RE_TITLE = re.compile(r'<title>([^<]+)</title>')


def _clean(s):
    return re.sub(r"\s+", " ", (s or "")).strip()


class Spider(_BaseSpider):
    def __init__(self):
        self.ext = {}
        self._cache = {}
        self._lock = threading.RLock()
        self._host = HOSTS[0]

    def getDependence(self):
        return ""

    def getName(self):
        return NAME

    def init(self, extend=""):
        try:
            if isinstance(extend, dict):
                self.ext = extend
            elif extend:
                self.ext = json.loads(extend)
        except Exception:
            self.ext = {}
        return ""

    def getCategory(self):
        return ""

    def getFilter(self):
        return {}

    def action(self, action):
        return ""

    def destroy(self):
        with self._lock:
            self._cache.clear()
        return ""

    def localProxy(self, param):
        return [404, "text/plain", ""]

    def isVideoFormat(self, url):
        text = str(url or "").lower()
        return bool(re.search(r"\.(?:m3u8|mp4|mkv|flv|avi|ts)(?:[?#]|$)", text))

    def _fetch(self, url, referer=""):
        headers = {
            "User-Agent": UA,
            "Accept": "text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8",
            "Accept-Language": "zh-CN,zh;q=0.9",
            "Accept-Encoding": "gzip",
            "Connection": "close",
        }
        if referer:
            headers["Referer"] = referer
        try:
            req = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(req, timeout=25, context=_SSL_CTX) as r:
                raw = r.read()
                if raw[:2] == b"\x1f\x8b":
                    try:
                        raw = gzip.decompress(raw)
                    except Exception:
                        pass
                return raw.decode("utf-8", "ignore")
        except Exception:
            return ""

    def _get(self, path, referer=""):
        if path.startswith("http"):
            url = path
        else:
            url = "https://" + self._host + (path if path.startswith("/") else "/" + path)
        with self._lock:
            cached = self._cache.get(url)
        if cached is not None:
            return cached
        body = self._fetch(url, referer)
        if not body and not path.startswith("http"):
            for host in HOSTS:
                if host == self._host:
                    continue
                alt = "https://" + host + (path if path.startswith("/") else "/" + path)
                body = self._fetch(alt, referer)
                if body:
                    self._host = host
                    url = alt
                    break
        with self._lock:
            self._cache[url] = body
        return body

    def _cards(self, body):
        out = []
        seen = set()
        for m in RE_CARD.finditer(body or ""):
            vid = m.group(1).strip()
            if vid in seen:
                continue
            seen.add(vid)
            out.append({
                "vod_id": "https://" + self._host + vid,
                "vod_name": _clean(m.group(3)) or "未知",
                "vod_pic": m.group(2) or "",
                "vod_remarks": "",
            })
        return out

    def _stream_url(self, body):
        m = RE_PLAYER.search(body or "")
        return (m.group(1) or "").strip() if m else ""

    def _page_title(self, body):
        m = RE_TITLE.search(body or "")
        if not m:
            return ""
        return _clean(m.group(1).rsplit(" - 91jav", 1)[0])

    def homeContent(self, *args):
        body = self._get("/")
        return {
            "class": [{"type_id": tid, "type_name": name} for tid, name in CLASSES],
            "list": self._cards(body),
            "page": 1,
            "pagecount": 999,
            "limit": 20,
            "total": 99999,
        }

    def categoryContent(self, tid, pg, filter, extend, *args):
        try:
            pg = int(pg)
        except Exception:
            pg = 1
        if pg < 1:
            pg = 1
        body = self._get("/theme/detail/%s/page/%d" % (tid, pg))
        vods = self._cards(body)
        return {"list": vods, "page": pg, "pagecount": 999,
                "limit": len(vods), "total": 99999}

    def detailContent(self, ids, *args):
        out = []
        for vid in ids:
            page = str(vid)
            if not page.startswith("http"):
                page = "https://" + self._host + (page if page.startswith("/") else "/" + page)
            body = self._get(page, referer=page)
            m3u8 = self._stream_url(body)
            if not m3u8:
                continue
            out.append({
                "vod_id": page,
                "vod_name": self._page_title(body) or "未知",
                "vod_pic": "",
                "vod_play_from": "91jav",
                "vod_play_url": "第1集$%s" % m3u8,
                "vod_remarks": "",
            })
        return {"list": out, "page": 1, "pagecount": 1,
                "limit": len(out), "total": len(out)}

    def playerContent(self, flag, id, vipFlags, *args):
        purl = str(id)
        # signed hls urls carry a ?sign=... tail -> match .m3u8 anywhere in the path
        if re.search(r"\.m3u8(?:[?#]|$)", purl):
            return {"parse": 0, "url": purl,
                    "header": {"Referer": "https://" + self._host + "/"}}
        if not purl.startswith("http"):
            purl = "https://" + self._host + (purl if purl.startswith("/") else "/" + purl)
        body = self._get(purl, referer=purl)
        url = self._stream_url(body)
        if not url:
            return {"parse": 0, "url": "", "msg": "stream url not found"}
        return {"parse": 0, "url": url,
                "header": {"Referer": "https://" + self._host + "/"}}

    def searchContent(self, key, quick=False, pg=1, *args):
        try:
            pg = int(pg)
        except Exception:
            pg = 1
        if pg < 1:
            pg = 1
        q = urllib.parse.quote(str(key))
        body = self._get("/search/%s/%d" % (q, pg))
        vods = self._cards(body)
        if not vods:
            # degrade to the latest feed so search never shows an empty screen
            body = self._get("/theme/detail/11/page/%d" % pg)
            vods = self._cards(body)
        return {"list": vods, "page": pg, "pagecount": 999,
                "limit": len(vods), "total": 99999}
